1	import java.util.List;
2	import java.util.ArrayList;
3	import java.util.Iterator;
4	
5	/**
6	 * This is the main class of the simulation, as it connects all the other classes
7	 * and runs the simulation. In general, the classes simulate a habitat in which
8	 * there are preys who feed on plants, and predators who compete for the preys.
9	 *
10	 * @version 2022.02.28
11	 */
12	public class Simulator
13	{
14	    private static final int LONG_SIMULATION_STEP_COUNT = 2000;
15	    // List of species in the field.
16	    private List<Species> species;
17	    // The current state of the field.
18	    private Field field;
19	    // keep track of the simulation steps.
20	    private SimulationStep simStep;
21	    // A graphical view of the simulation.
22	    private SimulatorView view;
23	    // keep track of the time in the simulation
24	    private Time time;
25	    // the habitat of the simulation
26	    private Habitat simulationHabitat;
27	    private boolean simulationIsOn;
28	
29	    private static final int DEFAULT_DELAY = 0;
30	
31	    /**
32	     * Construct a simulation field with default size.
33	     */
34	    public Simulator(Habitat simulationHabitat, Time time, List<Species> speciesInSimulation, Field field, SimulationStep simulationStepCounter, SimulatorView simulatorView)
35	    {
36	        this.simulationHabitat = simulationHabitat;
37	        this.time = time;
38	        this.species = speciesInSimulation;
39	        this.field = field;
40	        this.simStep = simulationStepCounter;
41	        this.view = simulatorView;
42	        this.simulationIsOn = true;
43	
44	        view.showStatus(simStep.getCurrentStep(), time.timeString(), simulationHabitat.getCurrentSeason(), simulationHabitat.getCurrentTemperature(), field);
45	    }
46	
47	
48	    /**
49	     * Run the simulation from its current state for a reasonably long period set as a class constant.
50	     */
51	    public void runLongSimulation()
52	    {
53	        simulate(LONG_SIMULATION_STEP_COUNT);
54	    }
55	    
56	    public void runHundredSteps()
57	    {
58	        simulate(100);
59	    }
60	
61	    /**
62	     * Run the simulation from its current state for the given number of steps.
63	     * Stop before the given number of steps if it ceases to be viable.
64	     *
65	     * @param numSteps (int) The number of steps to run for.
66	     */
67	    public void simulate(int numSteps)
68	    {
69	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
70	            delay(DEFAULT_DELAY);
71	            simulateOneStep();
72	            // delay(200);   // uncomment this to run more slowly
73	        }
74	    }
75	
76	    /**
77	     * Run the simulation from its current state for a single step.
78	     * Iterate over the whole field updating the state of each specie.
79	     */
80	    public void simulateOneStep()
81	    {
82	        if (simulationIsOn) {
83	            simStep.incStep();
84	            simulationHabitat.habitatStep();
85	            time.timeStep();
86	
87	            // the following variables are added here to reduce method calls:
88	            boolean isSpring = simulationHabitat.getIsSpring();
89	            boolean isNight = time.getIsNight();
90	            int currentTemperature = simulationHabitat.getCurrentTemperature();
91	            boolean yearPassed = simulationHabitat.yearPassed();
92	
93	            // Provide space for newborn species.
94	            List<Species> newSpecies = new ArrayList<>();
95	            // Let all species act.
96	            for(Iterator<Species> it = species.iterator(); it.hasNext(); )
97	            {
98	                Species specie = it.next();
99	                // Update the status of isSpring in the plants (done here to reduce coupling)
100	                if (specie instanceof Plant)
101	                {
102	                    Plant tempPlant = (Plant) specie;
103	                    if (tempPlant.getIsSpring() != isSpring) {
104	                        tempPlant.toggleIsSpring();
105	                    }
106	                }
107	
108	                specie.act(newSpecies, isNight, currentTemperature, yearPassed);
109	                if(! specie.isAlive()) {
110	                    it.remove();
111	                }
112	            }
113	
114	            // Add the newly born species to the main lists.
115	            species.addAll(newSpecies);
116	            view.showStatus(simStep.getCurrentStep(), time.timeString(), simulationHabitat.getCurrentSeason(), simulationHabitat.getCurrentTemperature(), field);
117	        }
118	    }
119	
120	    /**
121	     * Reset the simulation to a starting position.
122	     */
123	    public void endSimulation()
124	    {
125	        simStep.reset();
126	        species.clear();
127	        simulationIsOn = false;
128	    }
129	
130	    /**
131	     * Pause for a given time.
132	     * @param millisec (int) The time to pause for, in milliseconds
133	     */
134	    private void delay(int millisec)
135	    {
136	        try {
137	            Thread.sleep(millisec);
138	        }
139	        catch (InterruptedException ie) {
140	            // wake up
141	        }
142	    }
143	}
