1	import java.util.Collections;
2	import java.util.LinkedList;
3	import java.util.List;
4	import java.util.Random;
5	
6	/**
7	 * Represent a rectangular grid of field positions. Each position is able to store a single animal.
8	 *
9	 * @version 2022.02.28
10	 */
11	public class Field
12	{
13	    // A random number generator for providing random locations.
14	    private static final Random rand = Randomizer.getRandom();
15	    
16	    // The depth and width of the field.
17	    private int depth, width;
18	    // Storage for the animals.
19	    private Object[][] field;
20	
21	    /**
22	     * Represent a field of the given dimensions.
23	     *
24	     * @param depth The depth of the field.
25	     * @param width The width of the field.
26	     */
27	    public Field(int depth, int width)
28	    {
29	        this.depth = depth;
30	        this.width = width;
31	        field = new Object[depth][width];
32	    }
33	    
34	    /**
35	     * Empty the field.
36	     */
37	    public void clear()
38	    {
39	        for(int row = 0; row < depth; row++) {
40	            for(int col = 0; col < width; col++) {
41	                field[row][col] = null;
42	            }
43	        }
44	    }
45	    
46	    /**
47	     * Clear the given location.
48	     *
49	     * @param location The location to clear.
50	     */
51	    public void clear(Location location)
52	    {
53	        field[location.getRow()][location.getCol()] = null;
54	    }
55	    
56	    /**
57	     * Place an animal at the given location. If there is already an animal at the location it will be lost.
58	     *
59	     * @param species The animal to be placed.
60	     * @param row Row coordinate of the location.
61	     * @param col Column coordinate of the location.
62	     */
63	    public void place(Object species, int row, int col)
64	    {
65	        place(species, new Location(row, col));
66	    }
67	    
68	    /**
69	     * Place an animal at the given location. If there is already an animal at the location it will be lost.
70	     *
71	     * @param species The animal to be placed.
72	     * @param location Where to place the animal.
73	     */
74	    public void place(Object species, Location location)
75	    {
76	        field[location.getRow()][location.getCol()] = species;
77	    }
78	    
79	    /**
80	     * Return the animal at the given location, if any.
81	     *
82	     * @param location Where in the field.
83	     * @return The animal at the given location, or null if there is none.
84	     */
85	    public Object getObjectAt(Location location)
86	    {
87	        return getObjectAt(location.getRow(), location.getCol());
88	    }
89	    
90	    /**
91	     * Return the animal at the given location, if any.
92	     *
93	     * @param row The desired row.
94	     * @param col The desired column.
95	     * @return The animal at the given location, or null if there is none.
96	     */
97	    public Object getObjectAt(int row, int col)
98	    {
99	        return field[row][col];
100	    }
101	    
102	    /**
103	     * Generate a random location that is adjacent to the given location, or is the same location.
104	     * The returned location will be within the valid bounds of the field.
105	     *
106	     * @param location The location from which to generate an adjacency.
107	     * @return A valid location within the grid area.
108	     */
109	    public Location randomAdjacentLocation(Location location)
110	    {
111	        List<Location> adjacent = adjacentLocations(location);
112	        return adjacent.get(0);
113	    }
114	    
115	    /**
116	     * Get a shuffled list of the free adjacent locations.
117	     *
118	     * @param location Get locations adjacent to this.
119	     * @return A list of free adjacent locations.
120	     */
121	    public List<Location> getFreeAdjacentLocations(Location location)
122	    {
123	        List<Location> free = new LinkedList<>();
124	        List<Location> adjacent = adjacentLocations(location);
125	        for(Location next : adjacent) {
126	            if(getObjectAt(next) == null) {
127	                free.add(next);
128	            }
129	        }
130	        return free;
131	    }
132	    
133	    /**
134	     * Try to find a free location that is adjacent to the
135	     * given location. If there is none, return null.
136	     * The returned location will be within the valid bounds
137	     * of the field.
138	     * @param location The location from which to generate an adjacency.
139	     * @return A valid location within the grid area.
140	     */
141	    public Location freeAdjacentLocation(Location location)
142	    {
143	        // The available free ones.
144	        List<Location> free = getFreeAdjacentLocations(location);
145	        if(free.size() > 0) {
146	            return free.get(0);
147	        }
148	        else {
149	            return null;
150	        }
151	    }
152	
153	    /**
154	     * Return a shuffled list of locations adjacent to the given one.
155	     * The list will not include the location itself.
156	     * All locations will lie within the grid.
157	     * @param location The location from which to generate adjacencies.
158	     * @return A list of locations adjacent to that given.
159	     */
160	    public List<Location> adjacentLocations(Location location)
161	    {
162	        assert location != null : "Null location passed to adjacentLocations";
163	        // The list of locations to be returned.
164	        List<Location> locations = new LinkedList<>();
165	        if(location != null) {
166	            int row = location.getRow();
167	            int col = location.getCol();
168	            for(int roffset = -1; roffset <= 1; roffset++) {
169	                int nextRow = row + roffset;
170	                if(nextRow >= 0 && nextRow < depth) {
171	                    for(int coffset = -1; coffset <= 1; coffset++) {
172	                        int nextCol = col + coffset;
173	                        // Exclude invalid locations and the original location.
174	                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
175	                            locations.add(new Location(nextRow, nextCol));
176	                        }
177	                    }
178	                }
179	            }
180	            
181	            // Shuffle the list. Several other methods rely on the list
182	            // being in a random order.
183	            Collections.shuffle(locations, rand);
184	        }
185	        return locations;
186	    }
187	
188	    /**
189	     * Return the depth of the field.
190	     * @return The depth of the field.
191	     */
192	    public int getDepth()
193	    {
194	        return depth;
195	    }
196	    
197	    /**
198	     * Return the width of the field.
199	     * @return The width of the field.
200	     */
201	    public int getWidth()
202	    {
203	        return width;
204	    }
205	}
