1	import java.util.List;
2	import java.util.ArrayList;
3	
4	/**
5	 * A class representing the characteristics of a predator.
6	 * They are different from other animals because they eat any other
7	 * animal or predator whose strength is weaker.
8	 *
9	 * A horde of weaker predators can kill and eat a stronger predator.
10	 *
11	 *
12	 * @version 2022.03.01
13	 */
14	public class Predator extends Animal
15	{
16	    // The predator's strength, if it is strong enough it can attack other predators
17	    private final int strength;
18	
19	    /**
20	     * Create a new predator with given specifications.
21	     *
22	     * @param strength (int) the predator's strength
23	     * @param field (Field) the field where the simulation takes place
24	     * @param location (Location) the Location at which the predator should appear
25	     * @param name (String) the predator's name (its species' name)
26	     * @param maximumTemperature (int) the maximum temperature the predator can survive to
27	     * @param minimumTemperature (int) the minimum temperature an predator can survive to
28	     * @param nutritionalValue (int) the predator's nutritional value
29	     * @param reproductionProbability (double) the probability that the predator reproduces at each step after a given minimum breeding age
30	     * @param maxAge (int) the predator's life expectancy
31	     * @param breedingAge (int) the age at which predator can start to reproduce
32	     * @param maxLitterSize (int) the maximum number of children the predator can have in one reproduction
33	     * @param randomAge (boolean) whether or not predator should be created with a random age
34	     * @param hibernates (boolean) whether or not predator is able to hibernate
35	     * @param isNocturnal (boolean) whether or not predator is more active at night
36	     */
37	    public Predator (int strength, Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxAge, int breedingAge, int maxLitterSize,  boolean randomAge, boolean hibernates, boolean isNocturnal)
38	    {
39	        // call to the constructor of the Animal class
40	        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability, maxAge, breedingAge, maxLitterSize, randomAge, hibernates, isNocturnal);
41	
42	        this.strength = strength;
43	    }
44	
45	    /**
46	     * A predator's movement. It first checks if it attacked by a horde of another species of predators. If it is the case,
47	     * it dies and execution stops. If not, it first tries to reproduce, then to find a prey to eat in the neighboring cells,
48	     * and finally to move to either the cell the prey he ate was occupying or another free adjacent cell. If no adjacent cell
49	     * is available, it dies of overcrowding.
50	     *
51	     * @param newSpecies (List<Species>) A list to receive newly born animals.
52	     */
53	    protected void makeMove(List<Species> newSpecies)
54	    {
55	        ArrayList<Animal> neighboringAnimals = getNeighboringAnimalsList();
56	        checkForAttack(neighboringAnimals);
57	
58	        if (isAlive()) {
59	            if (canReproduce(neighboringAnimals)){
60	                reproduce(newSpecies);
61	            }
62	
63	            // Move towards a source of food if found.
64	            Location newLocation = null;
65	            if (isNotFull()) {
66	                newLocation = findFoodAndEat(neighboringAnimals);
67	            } 
68	
69	            if(newLocation == null) {
70	                // No food found - try to move to a free location.
71	                newLocation = getField().freeAdjacentLocation(getLocation());
72	            }
73	
74	            // See if it was possible to move.
75	            if(newLocation != null) {
76	                setLocation(newLocation);
77	            }
78	            else {
79	                // Overcrowding.
80	                setDead();
81	            }
82	        }
83	    }
84	
85	    /**
86	     * Tries to find a prey in one of the neighboring cell. If a prey is found, it is eaten and its location is returned.
87	     *
88	     * @param  neighboringAnimals (ArrayList<Animal>) A list of neighboring animals.
89	     * @return (Location) the location of the eaten prey, null if no prey was found.
90	     */
91	    private Location findFoodAndEat(ArrayList<Animal> neighboringAnimals)
92	    {
93	        for (Animal animal : neighboringAnimals) {
94	            if(!(animal instanceof Predator)){
95	                animal.setDead();
96	                foodLevel += animal.getNutritionalValue();
97	                return animal.getLocation();
98	            }
99	        }
100	        // No food found
101	        return null;
102	    }
103	
104	    /**
105	     * Check if predator if under attack from a horde of another species of predator. If a horde is attacking it and the horde's strength
106	     * is greater than the predator's one, the horde members eat it.
107	     *
108	     * @param  neighboringAnimals (ArrayList<Animal>) A list of neighboring animals.
109	     */
110	    private void checkForAttack(ArrayList<Animal> neighboringAnimals)
111	    {
112	        ArrayList<Predator> hordeMembers = new ArrayList<>();
113	
114	        for (int i =0; i < neighboringAnimals.size(); i++)
115	        {
116	            if (neighboringAnimals.get(i) instanceof Predator) {
117	
118	                Predator neighboringPredator = (Predator)neighboringAnimals.get(i);
119	                String nameOfInvestigatedHorde = neighboringPredator.getName();
120	                
121	                if(! this.getName().equals(nameOfInvestigatedHorde))
122	                {
123	                    int totalHordeStrength =  neighboringPredator.getStrength();
124	
125	                    hordeMembers.add(neighboringPredator);
126	                    for (int j =0; j < neighboringAnimals.size(); j++) {
127	                        if (nameOfInvestigatedHorde.equals(neighboringAnimals.get(j).getName())) {
128	                            Predator predatorObject = (Predator)neighboringAnimals.get(i);
129	                            totalHordeStrength += predatorObject.getStrength();
130	                            hordeMembers.add(predatorObject);
131	                        }
132	                    }
133	                    if (totalHordeStrength > strength) {
134	                        attackedByHorde(hordeMembers);
135	                        break;
136	                    } else {
137	                        hordeMembers.clear();
138	                    }
139	                }
140	            }
141	        }
142	    }
143	
144	    /**
145	     * Animal is under attack by a horde whose strength is greater than its own. It is eaten by the horde and dies. Its nutritional value
146	     * is therefore shared
147	     *
148	     * @param hordeMembers (ArrayList<Predator>) List of the predators constituting the horde.
149	     */
150	    private void attackedByHorde(ArrayList<Predator> hordeMembers)
151	    {
152	        // Sharing predator's nutritional value amongst the various horde members.
153	        int foodLevelAddedToEachHordeMember = this.getNutritionalValue() / hordeMembers.size();
154	        for (Predator predator : hordeMembers) {
155	            predator.incrementFoodLevel(foodLevelAddedToEachHordeMember);
156	        }
157	        this.setDead();
158	    }
159	
160	    /**
161	     * Creates the appropriate number of predators of the same species due to reproduction. These new predators of course share the same
162	     * features as their "parent" except the sex which is randomized, their age and foodLevel are not randomized.
163	     *
164	     * @param newOfThisKind (List<Species>) The list of species to which newborns must be added.
165	     */
166	    protected void reproduce(List<Species> newOfThisKind)
167	    {
168	        Field field = getField();
169	        if (field != null)
170	        {
171	            List<Location> free = field.getFreeAdjacentLocations(getLocation());
172	            int births = numberOfBirths();
173	            for(int b = 0; b < births && free.size() > 0; b++) {
174	                Location loc = free.remove(0);
175	                Predator young = new Predator(strength, field, loc, getName(), getMaximumTemperature(), getMinimumTemperature(), getNutritionalValue(), getReproductionProbability(), getMaxAge(), getBreedingAge(), getMaxLitterSize(),false, getHibernates(), getIsNocturnal());
176	                newOfThisKind.add(young);
177	            }
178	        }
179	    }
180	
181	    /**
182	     * Returns the predator's strength, public so that other predators can consult the strength of a pontential horde this predator could
183	     * be a part of.
184	     *
185	     * @return (int) the predator's strength.
186	     */
187	    public int getStrength() {
188	        return strength;
189	    }
190	}

