85	    /**
86	     * Create a simulator with the animals, habitat, and climate change
87	     * scenario asked by the user as well as all other necessary objects
88	     * for the simulation to run. The created Simulator is returned.
89	     *
90	     * @param chosenHabitat (String) The name of the habitat chosen by the user.
91	     * @param animalsToCreate (HashMap<String, Integer>) Keys are the animals' names and values are the number of each animal we need to create.
92	     * @param scenarioName (String) The name of the climate change scenario to implement in the simulation.
93	     * @return (Simulator) The created simulator.
94	     */
95	    public Simulator initializeSimulation(String chosenHabitat, HashMap<String, Integer> animalsToCreate, String scenarioName)
96	    {
97	        SimulationStep simulatorStepCounter = new SimulationStep();
98	        Field field = new Field(DEFAULT_DEPTH, DEFAULT_WIDTH);
99	        ClimateScenarios chosenClimateChangeScenario = createChosenClimateChangeScenario(scenarioName);
100	        Habitat simulationHabitat = createHabitat(chosenHabitat, simulatorStepCounter, chosenClimateChangeScenario);
101	        if (getNumberOfPlants() + getNumberOfAnimals(animalsToCreate) > calculateFieldArea()) {
102	            errorThrower.throwMessage("Too many animals were added for this habitat, please reduce the number of animals and try again");
103	            return null;
104	        }
105	        view = new SimulatorView(DEFAULT_DEPTH, DEFAULT_WIDTH, handler);
106	        populateWithAnimals(animalsToCreate, field);
107	        populateWithPlants(field);
108	        Time timeObject = new Time(simulatorStepCounter, DEFAULT_START_TIME);
109	        return new Simulator(simulationHabitat, timeObject ,speciesToEvolveInSimulation, field, simulatorStepCounter, view);
110	    }
