117	     * @param climateChangeScenario (ClimateScenarios) The created ClimateScenarios enum to be handed to the Habitat object.
118	     * @return (Habitat) the created Habitat object.
119	     */
120	    private Habitat createHabitat (String habitatName, SimulationStep simulatorStepCounter, ClimateScenarios climateChangeScenario)
121	    {
122	        if (habitatName != null) {
123	            habitatReader.extractDataFor(habitatName);
124	            Habitat chosenHabitat = new Habitat(simulatorStepCounter, climateChangeScenario ,habitatReader.getSpringTemperatures(), habitatReader.getSummerTemperatures(), habitatReader.getAutumnTemperatures(), habitatReader.getWinterTemperatures());
125	            habitatPlantConcentration = habitatReader.getPlantConcentration();
126	            return chosenHabitat;
127	        }
128	        else {
