134	    /**
135	     * Populate the simulation with the chosen animals.
136	     * First reading the data relating to each animal,
137	     * then creating and adding to the list of species the right number of each animal.
138	     *
139	     * @param animalsToCreate (HashMap<String, Integer>) The names and number of chosen animals.
140	     * @param field (Field) The field in which the animals will evolve.
141	     */
142	    private void populateWithAnimals(HashMap<String, Integer> animalsToCreate, Field field)
143	    {
144	        idxOfColorToUseNext = 0;
145	        Location freeLocationToPlaceAnimal;
146	
147	        for(String animalName : animalsToCreate.keySet()) {
148	            animalReader.extractDataFor(animalName);
149	            if (animalsToCreate.get(animalName) != 0)
150	            {
151	                // Retrieve appropriate data.
152	                String name = animalReader.getName();
153	                int maximumTemperature = animalReader.getMaximumTemperature();
154	                int minimumTemperature = animalReader.getMinimumTemperature();
155	                int maxAge = animalReader.getMaximumAge();
156	                int breedingAge = animalReader.getBreedingAge();
157	                double breedingProbability = animalReader.getBreedingProbability();
158	                int maxLitterSize = animalReader.getMaxLitterSize();
159	                int nutritionalValue = animalReader.getNutritionalValue();
160	                boolean hibernates = animalReader.canHibernate();
161	                boolean isNocturnal = animalReader.isNocturnal();
162	
163	                if (animalReader.isPredator()) {
164	                    // Predator object should be created, retrieving appropriate data.
165	                    int strength = animalReader.getStrength();
166	
167	                    // Creating the right number of Predator objects.
168	                    for (int i = 0; i < animalsToCreate.get(animalName); i++) {
169	                        freeLocationToPlaceAnimal = findAvailableLocation(field);
170	                        Predator newPredator = new Predator(strength, field, freeLocationToPlaceAnimal, name, maximumTemperature, minimumTemperature, nutritionalValue, breedingProbability, maxAge, breedingAge, maxLitterSize, RANDOM_ANIMAL_AGE, hibernates, isNocturnal);
171	                        speciesToEvolveInSimulation.add(newPredator);
172	                    }
173	                }
174	                else {
175	                    // Animal object should be created
176	                    // Creating the right number of Animal objects.
177	                    for (int i = 0; i < animalsToCreate.get(animalName); i++) {
178	                        freeLocationToPlaceAnimal = findAvailableLocation(field);
179	                        Animal newAnimal = new Animal(field, freeLocationToPlaceAnimal, name, maximumTemperature, minimumTemperature, nutritionalValue, breedingProbability, maxAge, breedingAge, maxLitterSize, RANDOM_ANIMAL_AGE, hibernates, isNocturnal);
180	                        speciesToEvolveInSimulation.add(newAnimal);
181	                    }
182	                }
183	
184	                // Setting the color for this species.
185	                view.setColor(name, listOfColorsForAnimals.get(idxOfColorToUseNext));
186	                idxOfColorToUseNext ++;
187	            }
188	        }
189	    }
