236	     * Calculate the area of the field to know the number of plants that should be created.
237	     *
238	     * @return (int) The field's area.
239	     */
240	    private int calculateFieldArea()
241	    {
242	        return DEFAULT_WIDTH * DEFAULT_DEPTH;
243	    }
