1	import java.util.ArrayList;
2	import java.util.List;
3	import java.util.Random;
4	
5	/**
6	 * Represent a habitat of the simulation.
7	 * Keep track of its seasons and temperature.
8	 *
9	 * @version 2022.02.28
10	 */
11	public class Habitat
12	{
13	    // holds the habitat's seasons
14	    private List<Season> seasons;
15	    // the number of steps before the season changes
16	    private static final int SEASON_CHANGE = 50;
17	    // hold the current season
18	    private Season currentSeason;
19	    // keep track of the simulation steps.
20	    private SimulationStep simStep;
21	    // hold a climate change scenario
22	    private ClimateScenarios changeScenario;
23	    // true if the current season is Spring
24	    private boolean isSpring;
25	    // A random number generator
26	    private static final Random rand = Randomizer.getRandom();
27	
28	    /**
29	     * Initialise the Habitat fields and fill the
30	     * seasons Hash map
31	     *
32	     * @param simStep (SimulatorStep) A SimulationStep object to keep track of the steps
33	     * @param changeScenario (ClimateScenarios) A climate change scenario
34	     * @param spring (int[]) An integer array with two elements: [0]= spring aveTemperature, [1] = spring tempChange
35	     * @param summer (int[]) An  integer array with two elements: [0]= summer aveTemperature, [1] = summer tempChange
36	     * @param autumn (int[]) An  integer array with two elements: [0]= autumn aveTemperature, [1] = autumn tempChange
37	     * @param winter (int[]) An  integer array with two elements: [0]= winter aveTemperature, [1] = winter tempChange
38	     */
39	    public Habitat(SimulationStep simStep, ClimateScenarios changeScenario, int[] spring, int[] summer, int[] autumn, int[] winter)
40	    {
41	        this.simStep = simStep;
42	        this.changeScenario = changeScenario;
43	
44	        // Season initialisations
45	        initialiseSeasons(spring, summer, autumn, winter);
46	        currentSeason = seasons.get(0);   // the simulation always starts with spring
47	        isSpring = true;
48	        climateChangeEffect(); // do the climate change effect on the first season
49	    }
50	
51	    /**
52	     * @return (String) The current season as a String
53	     */
54	    public String getCurrentSeason()
55	    {
56	        return currentSeason.getName();
57	    }
58	
59	    /**
60	     * @return (int) The current temperature of the current season as an int
61	     */
62	    public int getCurrentTemperature()
63	    {
64	        return currentSeason.getCurrentTemp().getTemperature();
65	    }
66	
67	    /**
68	     * @return (boolean) true if the current season is spring, false otherwise.
69	     */
70	    public boolean getIsSpring()
71	    {
72	        return isSpring;
73	    }
74	
75	    /**
76	     * @return (boolean) true if a year has passed in the simulation, false otherwise
77	     */
78	    public boolean yearPassed()
79	    {
80	        int step = simStep.getCurrentStep();
81	        // step+1 because step starts with 0
82	        return step != 0 && (step+1) % (SEASON_CHANGE * 4) == 0;
83	    }
84	
85	    /**
86	     * Method to be called on every step of the simulation for habitat conditions to be updated.
87	     *
88	     * 1) Increase the climate change effect if a year has passed
89	     * 2) Change the season if 'SEASON_CHANGE' steps have passed.
90	     * 3) Do the climate change effect on the new season
91	     * 4) Change the temperature each step
92	     */
93	    public void habitatStep()
94	    {
95	        int step = simStep.getCurrentStep();
96	
97	        // 1)
98	        if(yearPassed())
99	        {
100	            changeScenario.doClimateChange();
101	        }
102	
103	        // 2) & 3)
104	        if(step != 0 && step % SEASON_CHANGE == 0)
105	        {
106	            changeSeason();
107	            checkIsSpring();
108	            climateChangeEffect();
109	        }
110	
111	        // 4)
112	        randomizeTemperature();
113	    }
114	
115	    /**
116	     * Create and initialise the appropriate Season objects with the given values. Add them to the seasons List with the
117	     * order: spring, summer, autumn, winter.
118	     *
119	     * @param springValues (int[]) An integer array with two elements: [0]= spring aveTemperature, [1] = spring tempChange
120	     * @param summerValues (int[]) An integer array with two elements: [0]= summer aveTemperature, [1] = summer tempChange
121	     * @param autumnValues (int[]) An integer array with two elements: [0]= autumn aveTemperature, [1] = autumn tempChange
122	     * @param winterValues (int[]) An integer array with two elements: [0]= winter aveTemperature, [1] = winter tempChange
123	     */
124	    private void initialiseSeasons(int[] springValues, int[] summerValues, int[] autumnValues, int[] winterValues)
125	    {
126	        Season spring = new Season("spring", springValues[0], springValues[1]);
127	        Season summer = new Season("summer", summerValues[0], summerValues[1]);
128	        Season autumn = new Season("autumn", autumnValues[0], autumnValues[1]);
129	        Season winter = new Season("winter", winterValues[0], winterValues[1]);
130	
131	        // Initialise seasons and fill it
132	        seasons = new ArrayList<>();
133	        seasons.add(spring);
134	        seasons.add(summer);
135	        seasons.add(autumn);
136	        seasons.add(winter);
137	    }
138	
139	    /**
140	     * Change the current season according to the predefined order of seasons
141	     */
142	    private void changeSeason()
143	    {
144	        int seasonIndx = seasons.indexOf(currentSeason);
145	
146	        if(seasonIndx == seasons.size() -1) {
147	            currentSeason = seasons.get(0);
148	        }
149	        else {
150	            currentSeason = seasons.get(seasonIndx + 1);
151	        }
152	    }
153	
154	    /**
155	     * Make isSpring true or false depending on the current season.
156	     */
157	    private void checkIsSpring()
158	    {
159	        isSpring = currentSeason.getName().equals(seasons.get(0).getName());
160	    }
161	
162	    /**
163	     * Change the current season's temperature randomly according to the season's tempChange field
164	     */
165	    private void randomizeTemperature()
166	    {
167	        int randomize = rand.nextInt(2);
168	        int change = rand.nextInt(currentSeason.getTempChange() + 1);
169	        Thermometer currentTemp = currentSeason.getCurrentTemp();
170	
171	        // make sure that the temperature doesn't go beyond the temperature upper limit
172	        if (randomize == 0 && (getCurrentTemperature() + change) <= currentSeason.getUpperLimitTemp()) {
173	            currentTemp.incrementTemperature(change);
174	        }
175	        // make sure that the temperature doesn't go below the temperature lower limit
176	        else if(randomize == 1 && (getCurrentTemperature() - change) >= currentSeason.getLowerLimitTemp()) {
177	            currentTemp.incrementTemperature(- change);
178	        }
179	    }
180	
181	    /**
182	     * Increase the season's average temperature by the climate change scenario's concreteChange
183	     */
184	    private void climateChangeEffect()
185	    {
186	        currentSeason.incAveTemperature(changeScenario.getClimateChangeEffect());
187	    }
188	}

