1	import java.io.BufferedReader;
2	import java.io.FileReader;
3	import java.util.ArrayList;
4	
5	/**
6	 * A class to govern behavior of the various CSV Readers (one for plants, animals, scenarios, and habitats).
7	 * This class implements the actual "reading from a .csv file behavior" behaviour.
8	 *
9	 * @version 2022.02.28
10	 */
11	public abstract class CSVReader
12	{
13	    /**
14	     * Empty constructor for this class.
15	     */
16	    public CSVReader()
17	    {
18	    }
19	
20	    /**
21	     * Method to be called by children, it centralizes the CSV Readers operations by
22	     * orchestrating the process of reading data from the .csv file and populating
23	     * the appropriate fields with the read data.
24	     *
25	     * @param nameOfElementToLookFor (String) the name of the element which data must be extracted
26	     */
27	    public void extractDataFor(String nameOfElementToLookFor)
28	    {
29	        resetParameters();
30	        String[] extractedData = getDataFor(nameOfElementToLookFor);
31	        if (extractedData != null) {
32	            populateFields(extractedData);
33	        } else {
34	            System.out.println("ERROR: no data could be read for " + nameOfElementToLookFor);
35	        }
36	    }
37	
38	    /**
39	     * Reads the data relative to a given element in the appropriate .csv file
40	     * (the path to this file depends on the children class from which this method is called)
41	     * Source: technique to read .csv files was found on https://stackabuse.com/reading-and-writing-csvs-in-java/
42	     *
43	     * @param nameOfElementToLookFor (String) the name of the element which data must be extracted
44	     * @return (String[]) the extracted data
45	     */
46	    private String[] getDataFor(String nameOfElementToLookFor)
47	    {
48	        try(BufferedReader br = new BufferedReader(new FileReader(getFileName()))) {
49	            // Skip first line as they are headers.
50	            String line = br.readLine();
51	            while ((line=br.readLine()) != null) {
52	                String[] attributes = line.split(",");
53	                if (attributes[0].equals(nameOfElementToLookFor)) {
54	                    return attributes;
55	                }
56	            }
57	        } catch (Exception e) {
58	            System.out.println("Issue when parsing CSV");
59	        }
60	        return null;
61	    }
62	
63	    /**
64	     * Abstract method that must be overridden with the appropriate behaviours
65	     * needed to populate the fields of the child class.
66	     *
67	     * @param extractedData (String[]) The data extracted from the .csv file.
68	     */
69	    abstract void populateFields(String[] extractedData);
70	
71	    /**
72	     * Abstract method used to reset all the fields of a CSV Reader object when
73	     * the reading is done and another element ca be expected to be read.
74	     */
75	    abstract void resetParameters();
76	
77	    /**
78	     * Abstract method to return the name of the file containing the data to be read.
79	     *
80	     * @return (String) the file name.
81	     */
82	    abstract String getFileName();
83	
84	    /**
85	     * Returns a list of choices (of animals, habitats, and scenarios depending
86	     * on the child class it is called from) available to the user.
87	     * Source: technique to read from .csv files was found on https://stackabuse.com/reading-and-writing-csvs-in-java/
88	     *
89	     * @return (ArrayList<String>) The list of available choices.
90	     */
91	    public ArrayList<String> getChoicesList()
92	    {
93	        ArrayList<String> choicesList = new ArrayList<>();
94	        try(BufferedReader br = new BufferedReader(new FileReader(getFileName()))) {
95	            // Skip first line as they are headers.
96	            String line = br.readLine();
97	            while ((line=br.readLine()) != null) {
98	                String[] attributes = line.split(",");
99	                choicesList.add(attributes[0]);
100	            }
101	        } catch (Exception e) {
102	            e.printStackTrace();
103	            System.out.println("Issue when parsing CSV");
104	            return null;
105	        }
106	        return choicesList;
107	    }
108	}

