1	/**
2	 * An enum that specifies the values and actions of the different
3	 * climate change scenarios to approximate the real scenarios projected by the IPCC.
4	 *
5	 * @version 2022.02.28
6	 */
7	public enum ClimateScenarios
8	{
9	    SCENARIO1(0,0), SCENARIO2(1, 0.05), SCENARIO3(2, 0.15), SCENARIO4(3, 0.3);
10	    
11	    private double concreteChange;
12	    private final double changePercentage;
13	
14	    /**
15	     * Create an appropriate Climate Scenario
16	     *
17	     * @param concreteChange (int) hold the actual temperature change value
18	     * @param changePercentage (double) the change percentage that is added to the concreteChange each year
19	     */
20	    ClimateScenarios(int concreteChange, double changePercentage)
21	    {
22	        this.concreteChange = concreteChange;
23	        this.changePercentage = changePercentage;
24	    }
25	    
26	    /**
27	     * @return (int) the concreteChange as a rounded int
28	     */
29	    public int getClimateChangeEffect()
30	    {
31	        return (int) Math.round(concreteChange);
32	    }
33	
34	    /**
35	     * Increases the concreteChange by the changePercentage.
36	     */
37	    public void doClimateChange()
38	    {
39	        concreteChange = concreteChange + (changePercentage * concreteChange);
40	    }
41	}
