3	/**
4	 * This class reads from "habitats.csv" the information about all the habitats
5	 * that are available to be put in the simulation.
6	 *
7	 * @version 2022.02.28
8	 */
9	
10	public class HabitatCSVReader extends CSVReader {
11	    // List of minimum, average, and maximum temperatures for the winter.
12	    private int[] winterTemperatures;
13	    // List of minimum, average, and maximum temperatures for the spring.
14	    private int[] springTemperatures;
15	    // List of minimum, average, and maximum temperatures for the summer.
16	    private int[] summerTemperatures;
17	    // List of minimum, average, and maximum temperatures for the autumn.
18	    private int[] autumnTemperatures;
19	    // The concentration of plants in a given habitat.
20	    private double plantConcentration;
21	    // Tool to alert user about any potential error.
22	    private ErrorThrower errorThrower;
23	
24	    // Name of the CSV files containing data on fields.
25	    private static final String FILE_NAME = "habitats.csv";
26	
27	    /**
28	     * Build a HabitatCSVReader and initialize its fields.
29	     */
30	    public HabitatCSVReader() {
31	        errorThrower = new ErrorThrower();
32	        winterTemperatures = new int[2];
33	        autumnTemperatures = new int[2];
34	        springTemperatures = new int[2];
35	        summerTemperatures = new int[2];
36	        plantConcentration = 0;
37	    }
38	
39	    /**
40	     * Populate the fields with the data extracted from the .csv file. Fields are used to store data of the right type to be easily fetched
41	     * by the Initializer when trying to get information about a specific habitat.
42	     * Habitat name from the data is removed to facilitate reading, the first 12 elements are in groups of 2 relating to each season
43	     * (average temperature, and maximum change to temperature ), the 13th element is the plant concentration in that habitat.
44	     *
45	     * @param extractedData (String[]) the data from the CSV file relative to a specific habitat.
46	     */
47	    protected void populateFields(String[] extractedData)
48	    {
49	        extractedData = removeHabitatName(extractedData);
50	        if (extractedData.length != 9) {
51	            errorThrower.throwMessage("Habitat issue, please restart.");
52	        }
53	
54	        for(int i = 0; i < extractedData.length; i++) {
55	            if(i/2 == 0) {
56	                winterTemperatures[i%2] = Integer.parseInt(extractedData[i]);
57	            } else if (i/2 == 1) {
58	                springTemperatures[i%2] = Integer.parseInt(extractedData[i]);
59	            } else if (i/2 == 2) {
60	                summerTemperatures[i%2] = Integer.parseInt(extractedData[i]);
61	            } else if (i/2 == 3){
62	                autumnTemperatures[i%2] = Integer.parseInt(extractedData[i]);
63	            }
64	            plantConcentration = Double.valueOf(extractedData[8]);
65	        }
66	    }
67	
68	    /**
69	     * Set all parameters back to initial values before reading data for another habitat.
70	     */
71	    protected void resetParameters()
72	    {
73	        winterTemperatures = new int[2];
74	        springTemperatures = new int[2];
75	        summerTemperatures = new int[2];
76	        autumnTemperatures = new int[2];
77	        plantConcentration = 0;
78	
79	    }
80	
81	    /**
82	     * Returns the list of extracted data without the habitat's name (as this informaiton is known by the Initializer and will therefore
83	     * not be asked). The name is the first element of the attributes list.
84	     *
85	     * @param attributes (String[]) the data from the CSV file relative to a specific habitat.
86	     * @return (String[]) The data without the habitat's name.
87	     */
88	    private String[] removeHabitatName(String[] attributes)
89	    {
90	        String[] attributesWithoutHabitatName = Arrays.copyOfRange(attributes,1,attributes.length);
91	        return attributesWithoutHabitatName;
92	    }
93	
94	    /**
95	     * @return (String) The name of the file containing habitat data.
96	     */
97	    protected String getFileName() {
98	        return FILE_NAME;
99	    }
100	
101	    /**
102	     * @return (int[]) Minimum, average, and maximum temperatures for the winter.
103	     */
104	    public int[] getWinterTemperatures()
105	    {
106	        return winterTemperatures;
107	    }
108	
109	    /**
110	     * @return (int[]) Minimum, average, and maximum temperatures for the autumn.
111	     */
112	    public int[] getAutumnTemperatures() {
113	        return autumnTemperatures;
114	    }
115	
116	    /**
117	     * @return (int[]) Minimum, average, and maximum temperatures for the spring.
118	     */
119	    public int[] getSpringTemperatures() {
120	        return springTemperatures;
121	    }
122	
123	    /**
124	     * @return (int[]) Minimum, average, and maximum temperatures for the summer.
125	     */
126	    public int[] getSummerTemperatures() {
127	        return summerTemperatures;
128	    }
129	
130	    /**
131	     * @return (double) The concentration of plants in the habitat.
132	     */
133	    public double getPlantConcentration() {
134	        return plantConcentration;
135	    }
136	}

