5	/**
6	 * The GUIHandler handles the GUI by switching between views and coordinating
7	 * all the GUI's interactions with the simulation's "backend".
8	 *
9	 * @version 2022.02.28
10	 */
11	public class GUIHandler
12	{
13	    private Initializer simulationInitializer;
14	    private Simulator simulatorOnDisplay;
15	    private JFrame currentFrame;
16	    private ArrayList<String> animalChoices;
17	    private ArrayList<String> habitatChoices;
18	    private ArrayList<String> scenarioChoices;
19	
20	    /**
21	     * Build a GUIHandler with appropriate lists of choices for animals, habitats, and climate change scenarios.
22	     *
23	     * @param animalChoices (ArrayList<String>) List of animal choices.
24	     * @param habitatChoices (ArrayList<String>) List of habitat choices.
25	     * @param scenarioChoices (ArrayList<String>) List of climate change scenario choices.
26	     */
27	    public GUIHandler (Initializer initializer, ArrayList<String> animalChoices, ArrayList<String> habitatChoices, ArrayList<String> scenarioChoices)
28	    {
29	        simulationInitializer = initializer;
30	        this.animalChoices = animalChoices;
31	        this.habitatChoices = habitatChoices;
32	        this.scenarioChoices = scenarioChoices;
33	        showMenuView();
34	    }
35	
36	    /**
37	     * Set the menuView as the view currently on screen. The menu view is the view
38	     * that allows the user to set their choices concerning the simulation to be run.
39	     */
40	    private void showMenuView()
41	    {
42	        MenuView menuViewMaker = new MenuView(this, animalChoices, habitatChoices, scenarioChoices);
43	        JFrame menuFrame = menuViewMaker.createAndShow();
44	        menuFrame.pack();
45	        menuFrame.setVisible(true);
46	        currentFrame = menuFrame;
47	    }
48	
49	    /**
50	     * Switch to simulator view. The actual creation of the simulator view
51	     * (which is automatically displayed at its creation) is done by the Initializer
52	     * but this method is crucial as it gives the Initializer the information needed
53	     * to create the simulation the user asked for and hides the MenuView currently on display.
54	     *
55	     * @param chosenHabitat (String) The name of the chosen habitat.
56	     * @param selectedAnimals (HashMap<String, Integer>) Key-pair associations of animal names and number of those animals to be created.
57	     * @param chosenScenario (String) The name of the chosen climate change scenario.
58	     */
59	    public void switchToSimulatorView(String chosenHabitat,HashMap<String, Integer> selectedAnimals,String chosenScenario)
60	    {
61	        simulatorOnDisplay = simulationInitializer.initializeSimulation(chosenHabitat, selectedAnimals, chosenScenario);
62	        if (simulatorOnDisplay != null) {
63	            currentFrame.setVisible(false);
64	        }
65	    }
66	
67	    /**
68	     * Switch to menu view. This method allows users to launch a new simulation
69	     * in the same "session". It ends the currently running simulation and creates a totally
70	     * new instance of MenuView to be displayed.
71	     */
72	    public void switchToMenuView()
73	    {
74	        simulatorOnDisplay.endSimulation();
75	        currentFrame.setVisible(false);
76	        showMenuView();
77	    }
78	
79	    /**
80	     * Launches a long simulation (number of steps defined in the Simulator class).
81	     */
82	    public void launchLongSimulation()
83	    {
84	        new Thread(simulatorOnDisplay::runLongSimulation).start();
85	    }
86	
87	    /**
88	     * Launches a simulation long of 100 steps, allowing user to
89	     * periodically examine the state of the running simulation.
90	     */
91	    public void runHundredSteps()
92	    {
93	        new Thread(simulatorOnDisplay::runHundredSteps).start();
94	    }
95	
96	    /**
97	     * Launches a single step of simulation, allowing user to
98	     * have even greater details on the species' behaviors.
99	     */
100	    public void runOneStep()
101	    {
102	        simulatorOnDisplay.simulate(1);
103	    }
104	}

1	import java.util.Collections;
2	import java.util.LinkedList;
3	import java.util.List;
4	import java.util.Random;
5	
6	/**
7	 * Represent a rectangular grid of field positions. Each position is able to store a single animal.
8	 *
9	 * @version 2022.02.28
10	 */
11	public class Field
12	{
13	    // A random number generator for providing random locations.
14	    private static final Random rand = Randomizer.getRandom();
15	    
16	    // The depth and width of the field.
17	    private int depth, width;
18	    // Storage for the animals.
19	    private Object[][] field;
20	
21	    /**
22	     * Represent a field of the given dimensions.
23	     *
24	     * @param depth The depth of the field.
25	     * @param width The width of the field.
26	     */
27	    public Field(int depth, int width)
28	    {
29	        this.depth = depth;
30	        this.width = width;
31	        field = new Object[depth][width];
32	    }
33	    
34	    /**
35	     * Empty the field.
36	     */
37	    public void clear()
38	    {
39	        for(int row = 0; row < depth; row++) {
40	            for(int col = 0; col < width; col++) {
41	                field[row][col] = null;
42	            }
43	        }
44	    }
45	    
46	    /**
47	     * Clear the given location.
48	     *
49	     * @param location The location to clear.
50	     */
51	    public void clear(Location location)
52	    {
53	        field[location.getRow()][location.getCol()] = null;
54	    }
55	    
56	    /**
57	     * Place an animal at the given location. If there is already an animal at the location it will be lost.
58	     *
59	     * @param species The animal to be placed.
60	     * @param row Row coordinate of the location.
61	     * @param col Column coordinate of the location.
62	     */
63	    public void place(Object species, int row, int col)
64	    {
65	        place(species, new Location(row, col));
66	    }
67	    
68	    /**
69	     * Place an animal at the given location. If there is already an animal at the location it will be lost.
70	     *
71	     * @param species The animal to be placed.
72	     * @param location Where to place the animal.
73	     */
74	    public void place(Object species, Location location)
75	    {
76	        field[location.getRow()][location.getCol()] = species;
77	    }
78	    
79	    /**
80	     * Return the animal at the given location, if any.
81	     *
82	     * @param location Where in the field.
83	     * @return The animal at the given location, or null if there is none.
84	     */
85	    public Object getObjectAt(Location location)
86	    {
87	        return getObjectAt(location.getRow(), location.getCol());
88	    }
89	    
90	    /**
91	     * Return the animal at the given location, if any.
92	     *
93	     * @param row The desired row.
94	     * @param col The desired column.
95	     * @return The animal at the given location, or null if there is none.
96	     */
97	    public Object getObjectAt(int row, int col)
98	    {
99	        return field[row][col];
100	    }
101	    
102	    /**
103	     * Generate a random location that is adjacent to the given location, or is the same location.
104	     * The returned location will be within the valid bounds of the field.
105	     *
106	     * @param location The location from which to generate an adjacency.
107	     * @return A valid location within the grid area.
108	     */
109	    public Location randomAdjacentLocation(Location location)
110	    {
111	        List<Location> adjacent = adjacentLocations(location);
112	        return adjacent.get(0);
113	    }
114	    
115	    /**
116	     * Get a shuffled list of the free adjacent locations.
117	     *
118	     * @param location Get locations adjacent to this.
119	     * @return A list of free adjacent locations.
120	     */
121	    public List<Location> getFreeAdjacentLocations(Location location)
122	    {
123	        List<Location> free = new LinkedList<>();
124	        List<Location> adjacent = adjacentLocations(location);
125	        for(Location next : adjacent) {
126	            if(getObjectAt(next) == null) {
127	                free.add(next);
